The program reads the whole input, keeps a dictionary of variable values, and handles only two statement shapes:

- **Direct assignment:** `x <- N;` sets the variable to a constant.
- **Modular update:** `x <- (y + N) mod M;` sets the variable from another variable plus a constant, taken modulo `M`.

Comment lines (starting with `//`), blank lines and anything else that doesn't match are skipped. The final values of `a`–`h` and `TMP` are printed on one line in the requested format.

```python
import sys
import re

def main():
    text = sys.stdin.read()
    vals = {}
    assign_const = re.compile(r'^\s*([A-Za-z_]\w*)\s*<-\s*(-?\d+)\s*;?\s*$')
    assign_expr = re.compile(
        r'^\s*([A-Za-z_]\w*)\s*<-\s*\(\s*([A-Za-z_]\w*|-?\d+)\s*\+\s*([A-Za-z_]\w*|-?\d+)\s*\)\s*mod\s*(\d+)\s*;?\s*$'
    )

    def val(tok):
        if re.fullmatch(r'-?\d+', tok):
            return int(tok)
        return vals.get(tok, 0)

    for line in text.splitlines():
        s = line.strip()
        if not s or s.startswith('//'):
            continue
        m = assign_const.match(s)
        if m:
            vals[m.group(1)] = int(m.group(2))
            continue
        m = assign_expr.match(s)
        if m:
            var, x, y, mod = m.group(1), m.group(2), m.group(3), int(m.group(4))
            vals[var] = (val(x) + val(y)) % mod
            continue

    order = ['a', 'b', 'c', 'd', 'e', 'f', 'g', 'h', 'TMP']
    print(' '.join(f"{v} ?= {vals.get(v, 0)};" for v in order))

if __name__ == '__main__':
    main()
```
